// ==UserScript==
// @name         7zap Reveal Ultra Light Clean Enhanced v4
// @version      4.0
// @author       oumuamuax + assistant
// @namespace    https://github.com/oumuamuax/7zap-reveal-img-and-codes
// @description  Revela part numbers, elimina blur de imágenes y oculta mensajes premium (mejorado y más estable).
// @license      MIT
// @match        https://*.7zap.com/*
// @grant        none
// @run-at       document-end
// ==/UserScript==

(function () {
  'use strict';
  console.log('7zap Reveal v4: iniciando');

  /* -------------------------
     Util: aplicar CSS anti-blur
     ------------------------- */
  function applyAntiBlurCSS() {
    if (document.getElementById('7zap-universal-anti-blur')) return;
    const style = document.createElement('style');
    style.id = '7zap-universal-anti-blur';
    style.textContent = `
      /* Forzar eliminación de blur en imágenes y elementos con filter */
      img, .part-image, .scheme-image {
        -webkit-filter: none !important;
        filter: none !important;
        opacity: 1 !important;
      }
      /* Ocultar alertas de restricción */
      .alert-scheme, .premium-alert, .premium-message {
        display: none !important;
        visibility: hidden !important;
      }
      /* Asegurar que los "pills" no queden vacíos visualmente */
      .code-pill { min-width: 1.5em; display: inline-block; }
    `;
    document.head.appendChild(style);
    console.log('7zap Reveal v4: CSS anti-blur aplicado');
  }

  /* ---------------------------------------
     Interceptar fetch y XHR para detectar JSON
     --------------------------------------- */
  function installNetworkInterceptors() {
    // Intercept fetch
    const originalFetch = window.fetch;
    window.fetch = async function (...args) {
      try {
        const response = await originalFetch.apply(this, args);
        const contentType = response.headers.get && response.headers.get('content-type') || '';
        if (contentType.includes('application/json')) {
          // clonar y parsear sin alterar la respuesta original
          response.clone().json().then(json => {
            if (json && (json.parts || json.node || json.items)) {
              window.dispatchEvent(new CustomEvent('7zap:apiData', { detail: { url: args[0], json } }));
            }
          }).catch(()=>{});
        }
        return response;
      } catch (e) {
        return originalFetch.apply(this, args);
      }
    };

    // Intercept XHR
    const OriginalXHR = window.XMLHttpRequest;
    function ProxyXHR() {
      const xhr = new OriginalXHR();
      xhr.addEventListener('load', function () {
        try {
          const ct = xhr.getResponseHeader && xhr.getResponseHeader('content-type') || '';
          if (ct && ct.includes('application/json') && xhr.responseText) {
            try {
              const json = JSON.parse(xhr.responseText);
              if (json && (json.parts || json.node || json.items)) {
                window.dispatchEvent(new CustomEvent('7zap:apiData', { detail: { url: xhr.responseURL, json } }));
              }
            } catch (e) {}
          }
        } catch (e) {}
      });
      return xhr;
    }
    // Copiar prototipo para mantener compatibilidad
    ProxyXHR.prototype = OriginalXHR.prototype;
    window.XMLHttpRequest = ProxyXHR;
    console.log('7zap Reveal v4: interceptores de red instalados');
  }

  /* ---------------------------------------
     Lógica para revelar part codes en DOM
     --------------------------------------- */
  const knownParts = []; // array de objetos JSON recibidos por la API

  function handleApiData(e) {
    try {
      const json = e.detail.json;
      // Guardar partes si existen
      if (Array.isArray(json.parts) && json.parts.length) {
        json.parts.forEach(p => {
          if (p.part_code) knownParts.push(p);
        });
        revealFromKnownParts();
      }
      // Si la respuesta tiene node con scheme y numbers, también puede interesar
      if (json.node && json.node.name) {
        // no hacemos nada específico ahora, pero queda disponible
      }
    } catch (err) {
      console.error('7zap Reveal v4: error handleApiData', err);
    }
  }

  // Reemplaza strong con asteriscos usando onclick de clickToCopyPartNumber
  function revealMaskedStrong() {
    const strongs = document.querySelectorAll('strong:not([data-7zap-revealed])');
    strongs.forEach(s => {
      const text = (s.textContent || '').trim();
      if (text && /\*/.test(text)) {
        // buscar en el contenedor un elemento con onclick que contenga el PN real
        const container = s.closest('.partCodeInCatalog, tr, div') || s.parentElement;
        if (!container) return;
        const onclickEl = container.querySelector('[onclick*="clickToCopyPartNumber"]');
        if (onclickEl) {
          const onclick = onclickEl.getAttribute('onclick') || '';
          const match = onclick.match(/clickToCopyPartNumber\(['"]([^'"]+)['"]\)/);
          if (match && match[1]) {
            s.textContent = match[1];
            s.setAttribute('data-7zap-revealed', 'true');
            console.log('7zap Reveal v4: revelado desde onclick:', match[1]);
            return;
          }
        }
        // fallback: intentar buscar en knownParts por coincidencia parcial
        const found = knownParts.find(p => text.replace(/\*/g, '').length && p.part_code && p.part_code.includes(text.replace(/\*/g, '')));
        if (found) {
          s.textContent = found.part_code;
          s.setAttribute('data-7zap-revealed', 'true');
          console.log('7zap Reveal v4: revelado desde knownParts:', found.part_code);
        }
      }
    });
  }

  // Reemplaza elementos clásicos .copyPartNumberWrap
  function processClassicWraps() {
    const wraps = document.querySelectorAll('.copyPartNumberWrap:not([data-7zap-done])');
    wraps.forEach(el => {
      try {
        // si hay un onclick con el PN, extraerlo
        const html = el.innerHTML || '';
        const pnMatch = html.match(/clickToCopyPartNumber\(['"]([^'"]+)['"]\)/) || html.match(/navigator\.clipboard\.writeText\(["']([^"']+)["']\)/);
        if (pnMatch && pnMatch[1]) {
          // buscar el nodo visible (por ejemplo <strong> o .code-pill) y reemplazar
          const target = el.querySelector('strong, .code-pill, span') || el;
          target.textContent = pnMatch[1];
          console.log('7zap Reveal v4: reemplazado classic wrap con', pnMatch[1]);
        } else {
          // fallback: si knownParts tiene algo, intentar mapear por posición
          if (knownParts.length) {
            const first = knownParts[0];
            const target = el.querySelector('strong, .code-pill, span') || el;
            if (first && first.part_code) {
              target.textContent = first.part_code;
              console.log('7zap Reveal v4: fallback classic wrap con', first.part_code);
            }
          }
        }
      } catch (e) {
        console.error('7zap Reveal v4: error processClassicWraps', e);
      }
      el.setAttribute('data-7zap-done', 'true');
    });
  }

  // Usar knownParts para reemplazar spans .code-pill vacíos o truncados
  function revealFromKnownParts() {
    if (!knownParts.length) return;
    // buscar spans que contengan asteriscos o estén vacíos
    const pills = document.querySelectorAll('.code-pill.mono:not([data-7zap-done])');
    pills.forEach(p => {
      const txt = (p.textContent || '').trim();
      if (!txt || /\*/.test(txt) || txt.length < 4) {
        // intentar emparejar por nombre de parte cercano en el DOM (part-name, part_name)
        const parent = p.closest('.part-row, .part-main, .part-bottom, tr, .part');
        let matched = null;
        if (parent) {
          const nameEl = parent.querySelector('.part-name, .part_name, .partName, .part-name__title, .part-name__text, .part-name-text');
          const nameText = nameEl ? (nameEl.textContent || '').trim().toLowerCase() : '';
          if (nameText) {
            matched = knownParts.find(k => (k.part_name || '').toLowerCase().includes(nameText) || (k.part_code || '').toLowerCase().includes(nameText));
          }
        }
        if (!matched) matched = knownParts.shift(); // usar la primera si no hay match
        if (matched && matched.part_code) {
          p.textContent = matched.part_code;
          p.setAttribute('data-7zap-done', 'true');
          console.log('7zap Reveal v4: pill rellenado con', matched.part_code);
        }
      } else {
        p.setAttribute('data-7zap-done', 'true');
      }
    });
  }

  /* ---------------------------------------
     Observador de mutaciones para cambios dinámicos
     --------------------------------------- */
  function installMutationObserver() {
    const mo = new MutationObserver(mutations => {
      let shouldRun = false;
      for (const m of mutations) {
        if (m.type === 'childList' && (m.addedNodes && m.addedNodes.length)) {
          shouldRun = true;
        }
        if (m.type === 'attributes' && (m.attributeName === 'class' || m.attributeName === 'style')) {
          shouldRun = true;
        }
      }
      if (shouldRun) {
        // pequeñas demoras para dejar que el framework renderice
        setTimeout(() => {
          revealMaskedStrong();
          processClassicWraps();
          revealFromKnownParts();
        }, 120);
      }
    });
    mo.observe(document.documentElement || document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] });
    console.log('7zap Reveal v4: MutationObserver activo');
  }

  /* ---------------------------------------
     Ocultar mensajes premium específicos
     --------------------------------------- */
  function hidePremiumAlerts() {
    const texts = document.querySelectorAll('div, span, p');
    texts.forEach(el => {
      const t = (el.textContent || '').trim();
      if (t.includes('Users without a premium tariff can view no more than') || t.includes('premium')) {
        el.style.display = 'none';
        el.dataset.zapHidden = 'true';
        console.log('7zap Reveal v4: ocultado mensaje premium');
      }
    });
  }

  /* ---------------------------------------
     Inicialización
     --------------------------------------- */
  function init() {
    applyAntiBlurCSS();
    installNetworkInterceptors();
    installMutationObserver();
    window.addEventListener('7zap:apiData', handleApiData);
    // Ejecutar una pasada inicial
    setTimeout(() => {
      revealMaskedStrong();
      processClassicWraps();
      revealFromKnownParts();
      hidePremiumAlerts();
    }, 600);
    // Reaplicar periódicamente por si algo se restaura
    setInterval(() => {
      applyAntiBlurCSS();
      revealMaskedStrong();
      processClassicWraps();
      revealFromKnownParts();
      hidePremiumAlerts();
    }, 5000);
  }

  // arrancar cuando el DOM esté listo
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
